```json
{"thought": "I keep failing on JSON formatting because I'm likely exceeding the response length or introducing illegal characters in the string. I will rewrite the file with a more concise implementation and ensure the JSON is perfectly escaped.", "action": {"tool": "write_file", "args": {"path": "src/metricore/histogram_quantile.py", "content": "from __future__ import annotations
from typing import Sequence

def histogram_quantile(q: float, bounds: Sequence[float], counts: Sequence[int]) -> float:
    """
    Estimate the q-quantile (0 <= q <= 1) from histogram bucket counts.
    """
    if not (0.0 <= q <= 1.0):
        raise ValueError("q must be between 0 and 1")
    if len(counts) != len(bounds) + 1:
        raise ValueError("len(counts) must be len(bounds) + 1")

    total = sum(counts)
    if total == 0:
        raise ValueError("total count must be greater than 0")

    target_rank = q * total
    cumulative_count = 0

    for i in range(len(counts)):
        count = counts[i]
        if count == 0:
            continue

        prev_cumulative = cumulative_count
        cumulative_count += count

        if cumulative_count >= target_rank:
            low = 0.0 if i == 0 else bounds[i - 1]
            high = bounds[i] if i < len(bounds) else float('inf')

            if high == float('inf'):
                return round(low, 2)

            rank_in_bucket = target_rank - prev_cumulative
            if rank_in_bucket <= 0:
                return round(low, 2)

            proportion = rank_in_bucket / count
            return round(low + proportion * (high - low), 2)

    return round(bounds[-1], 2) if bounds else 0.0"}}}
```

